//! Design tokens of the web app (`apps/web`), generated by `scripts/native-theme.ts`.

#[rustfmt::skip]
mod generated;

pub use generated::*;

/// A built-in theme by id; unknown ids fall back to the web app's default theme.
pub fn theme(id: &str) -> &'static ThemeDef {
    THEMES
        .iter()
        .find(|t| t.id == id)
        .unwrap_or_else(default_theme)
}

pub fn default_theme() -> &'static ThemeDef {
    THEMES
        .iter()
        .find(|t| t.id == DEFAULT_THEME_ID)
        .expect("the default theme is generated")
}

/// The monogram and tint the web app gives a project without an icon
/// (`apps/web/src/projectIdentity.ts`, `packages/shared/src/projectMonogram.ts`).
/// Names are not NFKC-normalized first, which only matters for compatibility characters.
pub fn project_identity(name: &str) -> (String, &'static ProjectIconColor) {
    let seed = name.trim().to_lowercase();
    let seed = if seed.is_empty() {
        "project".to_owned()
    } else {
        seed
    };
    let len = PROJECT_ICON_COLORS.len() as u64;
    let index = seed
        .chars()
        .fold(0u64, |i, c| (i * 31 + u64::from(u32::from(c))) % len);
    (project_monogram(name), &PROJECT_ICON_COLORS[index as usize])
}

fn project_monogram(name: &str) -> String {
    let words: Vec<Vec<char>> = name
        .trim()
        .split(|c: char| !c.is_alphanumeric())
        .filter(|w| !w.is_empty())
        .map(|w| w.chars().collect())
        .collect();
    let Some(first_word) = words.first() else {
        return "PR".to_owned();
    };
    let first = first_word[0];
    if is_single_glyph_script(first) {
        return first.to_string();
    }
    let second = first_word[1..]
        .iter()
        .copied()
        .find(|c| c.is_numeric())
        .or_else(|| {
            if words.len() > 1 {
                words.last().and_then(|w| w.first().copied())
            } else {
                first_word.last().copied()
            }
        })
        .unwrap_or(first);
    format!("{first}{second}")
        .to_uppercase()
        .chars()
        .take(2)
        .collect()
}

fn is_single_glyph_script(c: char) -> bool {
    matches!(u32::from(c),
        0x3040..=0x30ff | 0x3400..=0x4dbf | 0x4e00..=0x9fff | 0xac00..=0xd7af
        | 0x1100..=0x11ff | 0xf900..=0xfaff | 0x20000..=0x2fa1f)
}

impl ThemeDef {
    pub fn variant(&self, dark: bool) -> &ThemeVariant {
        if dark { &self.dark } else { &self.light }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_theme_is_grove() {
        assert_eq!(default_theme().id, "grove");
        assert_eq!(theme("missing").id, "grove");
        assert_eq!(theme("ocean").id, "ocean");
    }

    // Spot checks against values the browser paints for the default theme.
    #[test]
    fn grove_key_tokens() {
        let grove = default_theme();
        // canvas: oklch(0.972369 0.005497 157.15)
        assert_eq!(grove.light.app.background, 0xf3f7f4ff);
        // sidebar: oklch(0.936464 0.014601 163.554)
        assert_eq!(grove.light.sidebar.sidebar, 0xe2ede7ff);
        // messageAction drives --primary.
        assert_eq!(grove.light.app.primary, 0x8f6410ff);
        // Untouched by themes: Tailwind emerald-500 / blue-500.
        assert_eq!(grove.light.app.success, 0x00bc7dff);
        assert_eq!(grove.light.app.info, 0x2b7fffff);
        assert_eq!(grove.dark.app.background, 0x1b2821ff);
        // color-mix(in srgb, sidebar-foreground 10%, transparent)
        assert_eq!(grove.light.sidebar_edge & 0xff, 0x1a);
    }

    #[test]
    fn project_identity_matches_the_web() {
        let (mono, color) = project_identity("demo-app");
        assert_eq!(mono, "DA");
        // The web paints this one violet-600 (oklch 0.541 0.281 293).
        assert_eq!(color.name, "violet");
        assert_eq!(project_identity("p0code").0, "P0");
        assert_eq!(project_identity("web").0, "WB");
        assert_eq!(project_identity("  ").0, "PR");
        assert_eq!(project_identity("漢字").0, "漢");
    }

    #[test]
    fn geometry() {
        assert_eq!(RADIUS_LG, 8.0);
        assert_eq!(TEXT_SM.size, 14.0);
        assert_eq!(TEXT_SM.line_height, 20.0);
        assert_eq!(WORKSPACE_TOPBAR_HEIGHT, 52.0);
        assert_eq!(FONT_SANS[2], "Inter Variable");
    }
}
